"use strict";(self.webpackChunkphmc_tools=self.webpackChunkphmc_tools||[]).push([[1654],{1654:(e,n,s)=>{s.d(n,{POSTES_FR:()=>l});const t="Fortes capacit\xe9s d'observation.",i="Envie d'apprendre et de s'adapter.",r="Compr\xe9hension de base de la terminologie m\xe9dicale.",a="\xcatre actuellement inscrit(e) dans une facult\xe9 de m\xe9decine accr\xe9dit\xe9e. Avoir termin\xe9 les enseignements pr\xe9cliniques est pr\xe9f\xe9rable.",o=(e,n)=>({nom:e,cle:e,role:n,presentation:"Lorsque le travail que vous accomplissez chaque jour a un impact crucial sur la vie des autres... (suite de votre pr\xe9sentation)",competence1:t,competence2:i,competence3:r,diplome:a}),l={"Rotation (Medical Students)":{nom:"Externe en M\xe9decine (Rotation)",cle:"Externe en M\xe9decine (Rotation)",role:"Externe / \xc9tudiant(e) en M\xe9decine",presentation:"Lorsque le travail que vous accomplissez chaque jour a un impact crucial sur la vie des autres, chaque effort, chaque d\xe9tail et chaque seconde comptent. En tant qu'\xe9tudiant(e) en m\xe9decine \xe0 temps plein au sein de notre programme de rotation, vous d\xe9couvrirez de l'int\xe9rieur le fonctionnement quotidien d'un h\xf4pital. Les \xe9tudiants en m\xe9decine se trouvent \xe0 un moment charni\xe8re de leur parcours universitaire et de leur future carri\xe8re lorsqu'ils recherchent un stage formel. Gr\xe2ce \xe0 notre programme, les \xe9tudiants acquerront une exp\xe9rience de terrain aux c\xf4t\xe9s de professionnels de sant\xe9 forts de plusieurs d\xe9cennies d'exp\xe9rience, ce qui les aidera \xe0 se pr\xe9parer \xe0 un domaine m\xe9dical en constante \xe9volution. \n\nCe programme s'adresse \xe0 celles et ceux qui sont actuellement inscrits dans une facult\xe9 de m\xe9decine accr\xe9dit\xe9e et qui ont termin\xe9 leurs enseignements pr\xe9cliniques. Les \xe9tudiants devront travailler aux c\xf4t\xe9s de nos professionnels de sant\xe9 et auront la possibilit\xe9 de les accompagner dans diff\xe9rents services. Ils devront \xe9galement r\xe9aliser une s\xe9rie de travaux et de projets tout au long du programme, qui les pr\xe9pareront \xe0 leur future carri\xe8re en m\xe9decine. \n\n Si vous souhaitez candidater \xe0 ce programme, veuillez d\xe9poser votre candidature via notre site. Nous nous r\xe9jouissons de vous lire !",competence1:t,competence2:i,competence3:r,diplome:a},Dentist:o("Dentiste","Dentiste"),"Attending Physician":o("M\xe9decin Titulaire","M\xe9decin Titulaire"),"Physical Therapist":o("Kin\xe9sith\xe9rapeute","Kin\xe9sith\xe9rapeute"),Pharmacist:o("Pharmacien(ne)","Pharmacien(ne)"),"Surgical Resident":o("Interne en Chirurgie","Interne en M\xe9decine"),"Physician Assistant":o("Assistant(e) M\xe9decin","Assistant(e) M\xe9decin"),"Resident Physician":{nom:"Interne en M\xe9decine",cle:"Interne en M\xe9decine",role:"Interne en M\xe9decine",presentation:"Un interne en m\xe9decine (\xab resident \xbb) est un m\xe9decin qui a termin\xe9 ses \xe9tudes de m\xe9decine et poursuit sa formation dans une sp\xe9cialit\xe9 m\xe9dicale pr\xe9cise. Les internes travaillent dans les h\xf4pitaux et \xe9tablissements de sant\xe9 sous la supervision de m\xe9decins titulaires exp\xe9riment\xe9s. Leurs missions comprennent le diagnostic et le traitement des patients, la r\xe9alisation d'actes m\xe9dicaux et l'apprentissage des subtilit\xe9s de leur sp\xe9cialit\xe9. Les internes jouent un r\xf4le essentiel dans la prise en charge des patients : ils acqui\xe8rent une exp\xe9rience pratique, d\xe9veloppent leurs comp\xe9tences cliniques et gagnent progressivement en autonomie dans leur exercice. Cette phase de formation dure g\xe9n\xe9ralement plusieurs ann\xe9es, apr\xe8s lesquelles ils peuvent viser une certification (\xab board certification \xbb) dans la sp\xe9cialit\xe9 choisie.",competence1:"Un esprit critique, un jugement d\xe9cisif et la capacit\xe9 de travailler seul(e) comme en \xe9quipe sont requis.\n- La capacit\xe9 de travailler dans un environnement stressant et d'agir de mani\xe8re appropri\xe9e est indispensable. Le ou la candidat(e) doit \xeatre en bonne condition physique pour r\xe9pondre \xe0 des exigences telles que d\xe9placer et soulever des patients, avec une mobilit\xe9 compl\xe8te du corps, une dext\xe9rit\xe9 manuelle des doigts et une bonne coordination \u0153il-main.",competence2:"De solides comp\xe9tences relationnelles pour \xe9changer avec les patients et le personnel sont obligatoires.\n- Avoir au moins vingt-six (26) ans et poss\xe9der une adresse l\xe9gale dans l'\xc9tat de San Andreas ;",competence3:"Avoir un \xe9tat de sant\xe9 physique et mental satisfaisant pour exercer les fonctions essentielles du poste en toute s\xe9curit\xe9.\n- Ne pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit r\xe9cent.",diplome:"\xcatre titulaire d'un dipl\xf4me d'une universit\xe9 ou d'un \xe9tablissement dont l'accr\xe9ditation est reconnue aux \xc9tats-Unis d'Am\xe9rique. \n- \xcatre docteur en m\xe9decine (MD) ou docteur en m\xe9decine ost\xe9opathique (DO) agr\xe9\xe9(e) dans l'\xc9tat de San Andreas.\n- Avoir d\xe9j\xe0 exerc\xe9 en m\xe9decine d'urgence ou en m\xe9decine interne."},"Counseling Psychologist":{nom:"Psychologue Conseil",cle:"Psychologue Conseil",role:"Psychologue",presentation:"Stage d'entr\xe9e de carri\xe8re pour les futur(e)s psychologues...",competence1:"Principes de base de la psychologie.",competence2:"Comp\xe9tences de communication.",competence3:"Empathie.",diplome:"\xcatre inscrit(e) ou dipl\xf4m\xe9(e) d'une licence ou d'un master (Bachelor's / Master's) en psychologie."},"Resident Psychiatrist":{nom:"Psychologue R\xe9sident(e)",cle:"Psychologue R\xe9sident(e)",role:"Psychologue",presentation:"Poste de formation pour les psychologues dipl\xf4m\xe9(e)s de troisi\xe8me cycle...",competence1:"Th\xe9ories psychologiques avanc\xe9es.",competence2:"Exp\xe9rience en \xe9valuation clinique.",competence3:"Collaboration en \xe9quipe.",diplome:"Doctorat (Ph.D./Psy.D.) en psychologie. \xc9ligibilit\xe9 \xe0 la licence d'exercice."},"Attending Psychiatrist":{nom:"Psychiatre Titulaire",cle:"Psychiatre Titulaire",role:"Psychiatre",presentation:"M\xe9decin dipl\xf4m\xe9(e) sp\xe9cialis\xe9(e) en psychiatrie...",competence1:"Expertise en psychopharmacologie.",competence2:"Qualit\xe9s de leadership.",competence3:"Gestion de cas complexes.",diplome:"MD/DO. Internat en psychiatrie. Certification (board certification). Licence d'exercice."},Psychologist:{nom:"Psychologue",cle:"Psychologue",role:"Psychologue",presentation:"Propose des services de conseil et de th\xe9rapie...",competence1:"\xc9valuation et intervention de crise.",competence2:"Connaissance des ressources locales.",competence3:"Comp\xe9tence culturelle.",diplome:"MSW. Licence LCSW."},Janitor:{nom:"Agent d'Entretien",cle:"Agent d'Entretien",role:"Personnel Polyvalent",presentation:"Un agent d'entretien r\xe9alise diverses t\xe2ches de nettoyage, d'assainissement et d'entretien dans et autour des b\xe2timents de l'h\xf4pital ou des sites d'\xe9v\xe9nements officiels, ainsi que de petits travaux d'entretien des espaces ext\xe9rieurs attenants. Il doit s'assurer que tout est en \xe9tat de fonctionnement et, dans le cas contraire, prendre en charge le probl\xe8me et le r\xe9parer imm\xe9diatement. L'\xe9tendue des missions est tr\xe8s vari\xe9e. Elle est toutefois principalement d'ordre pratique et technique : nettoyer les escaliers, faire fonctionner le chauffage central et garantir le bon fonctionnement g\xe9n\xe9ral de l'h\xf4pital.",competence1:"Avoir au moins vingt et un (21) ans et poss\xe9der une adresse l\xe9gale dans l'\xc9tat de San Andreas.\nNe pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit r\xe9cent.",competence2:"Savoir bien travailler en \xe9quipe tout en faisant preuve d'autonomie par moments.\n\xcatre en bonne sant\xe9 et en bonne condition physique pour supporter les efforts fr\xe9quents tels que soulever, se pencher et s'agenouiller, ainsi que rester debout, marcher et atteindre des endroits dans l'h\xf4pital.",competence3:"Respecter toutes les politiques de l'h\xf4pital et ses r\xe8gles \xe9thiques.\nAvoir une image publique irr\xe9prochable et une empreinte notable dans les r\xe9seaux sociaux et les cercles professionnels de la ville.",diplome:"Avoir d\xe9j\xe0 de l'exp\xe9rience dans des travaux d'entretien lors de postes pr\xe9c\xe9dents, ou avoir suivi une formation procurant cette exp\xe9rience."},"Cafeteria Staff":{nom:"Personnel de Restauration",cle:"Personnel de Restauration",role:"Personnel Polyvalent",presentation:"Le personnel de restauration pr\xe9pare les repas selon les menus, les restrictions alimentaires ou nutritionnelles particuli\xe8res et le nombre de portions \xe0 servir. Il doit veiller \xe0 ce que chacun re\xe7oive un repas compatible avec sa tol\xe9rance digestive.\nLe poste de cuisinier ne doit pas \xeatre sous-estim\xe9 : il comporte de nombreuses exigences et responsabilit\xe9s importantes, comme nettoyer la cuisine, d\xe9couper et cuisiner viandes, poissons et volailles, ainsi que proposer un menu vari\xe9 au personnel de l'h\xf4pital et aux patients.",competence1:"Avoir au moins vingt et un (21) ans et poss\xe9der une adresse l\xe9gale dans l'\xc9tat de San Andreas.",competence2:"Ne pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit r\xe9cent.",competence3:"Respecter toutes les politiques de l'h\xf4pital et ses r\xe8gles \xe9thiques.",diplome:"Avoir d\xe9j\xe0 de l'exp\xe9rience."},"Human Resources Assistant":{nom:"Assistant(e) Ressources Humaines",cle:"Assistant(e) Ressources Humaines",role:"Charg\xe9(e) de Recrutement",presentation:"En tant que membre des Ressources Humaines, vous aurez la possibilit\xe9 de consacrer votre temps \xe0 aider le personnel de terrain de l'h\xf4pital dans l'exercice de ses fonctions. Vous devrez mettre \xe0 profit votre exp\xe9rience ant\xe9rieure pour mener \xe0 bien vos missions et pr\xe9server une image publique irr\xe9prochable, pour vous-m\xeame comme pour l'h\xf4pital. Vous aiderez en outre chaque service pour les questions de recrutement et d'int\xe9gration, r\xe9aliserez des v\xe9rifications d'ant\xe9c\xe9dents, m\xe8nerez des entretiens et transmettrez les comptes rendus aux responsables et aux directeurs.",competence1:"Avoir au moins vingt et un (21) ans et poss\xe9der une adresse l\xe9gale dans l'\xc9tat de San Andreas.",competence2:"Ne pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit r\xe9cent.",competence3:"Respecter toutes les politiques de l'h\xf4pital et ses r\xe8gles \xe9thiques.",diplome:"Avoir d\xe9j\xe0 de l'exp\xe9rience."},"Registered Nurse":{nom:"Infirmier(\xe8re) Dipl\xf4m\xe9(e) d'\xc9tat (RN)",cle:"Infirmier(\xe8re) Dipl\xf4m\xe9(e) d'\xc9tat (RN)",role:"Infirmier(\xe8re)",presentation:"R\xe9aliser des \xe9valuations compl\xe8tes des patients, \xe9laborer des plans de soins individualis\xe9s et en \xe9valuer les r\xe9sultats.\nAdministrer les m\xe9dicaments, r\xe9aliser des soins et des actes, et apporter un soutien \xe9motionnel aux patients et \xe0 leurs familles.\nSuperviser et d\xe9l\xe9guer des t\xe2ches aux infirmiers auxiliaires (LVN), aux internes en soins infirmiers et aux autres personnels de soutien, tout en veillant au respect des protocoles de l'h\xf4pital. \nInformer les patients et leurs familles sur les diagnostics, les plans de traitement et les soins apr\xe8s la sortie pour favoriser la sant\xe9 et la gu\xe9rison.\nTravailler en \xe9troite collaboration avec les m\xe9decins, les praticiens de pratique avanc\xe9e et les autres professionnels de sant\xe9 pour coordonner une prise en charge globale.\nAgir en premi\xe8re intervention lors des urgences m\xe9dicales, en engageant si n\xe9cessaire les gestes de sauvetage.",competence1:"Doit d\xe9montrer sa capacit\xe9 \xe0 poser des jugements cliniques s\xfbrs et \xe0 hi\xe9rarchiser efficacement les priorit\xe9s dans un environnement de soins dynamique.\nDoit \xeatre efficace dans les situations de forte pression, y compris les urgences.\nDoit \xeatre en bonne condition physique pour soulever, d\xe9placer et repositionner les patients, et pouvoir r\xe9pondre aux exigences physiques de gardes de 12 heures. \nDoit avoir de solides capacit\xe9s de communication orale et \xe9crite pour \xe9changer avec des patients, des familles et des \xe9quipes vari\xe9s.",competence2:"Doit avoir une sant\xe9 physique et mentale satisfaisante pour exercer les fonctions essentielles en toute s\xe9curit\xe9, et respecter toutes les politiques de l'h\xf4pital et les normes \xe9thiques professionnelles.\nUne exp\xe9rience clinique pr\xe9alable en milieu hospitalier ou de soins aigus est pr\xe9f\xe9rable mais non obligatoire pour les jeunes dipl\xf4m\xe9(e)s. ",competence3:"\n(( Si vous jouez une exp\xe9rience clinique pr\xe9alable, elle doit figurer dans l'histoire de votre personnage. ))\nDoit avoir au moins 20 \xe0 21 ans.\nNe doit pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit pertinent par le pass\xe9..",diplome:"Doit \xeatre titulaire d'un Associate's Degree in Nursing (ADN) ou d'un Bachelor of Science in Nursing (BSN) d'un programme accr\xe9dit\xe9. Un BSN est pr\xe9f\xe9r\xe9. (( Cela doit faire partie de l'histoire de votre personnage. ))\nDoit poss\xe9der une licence active et sans restriction de Registered Nurse (RN) de San Andreas. (( PNJ ))\nDoit d\xe9tenir une certification Basic Life Support (BLS) en cours de validit\xe9. Les certifications Advanced Cardiac Life Support (ACLS), Pediatric Advanced Life Support (PALS) et d'autres certifications propres \xe0 un service (ex. TNCC pour les infirmiers en traumatologie) sont \xe9galement bienvenues. (( Cela doit faire partie de l'histoire de votre personnage. ))\nDoit r\xe9sider dans l'\xc9tat de San Andreas ou \xeatre en mesure de s'y installer."},"Nurse Practitioner":{nom:"Infirmier(\xe8re) en Pratique Avanc\xe9e (NP)",cle:"Infirmier(\xe8re) en Pratique Avanc\xe9e (NP)",role:"Infirmier(\xe8re) en Pratique Avanc\xe9e",presentation:"R\xe9aliser des bilans de sant\xe9 complets, comprenant le recueil de l'historique, l'examen physique et les examens diagnostiques.\n\xc9laborer et mettre en \u0153uvre des plans de traitement fond\xe9s sur les preuves, adapt\xe9s aux besoins de chaque patient.\nPrescrire des m\xe9dicaments, demander des examens diagnostiques et recommander des interventions th\xe9rapeutiques dans le respect de la r\xe9glementation du San Andreas Board of Nursing.\nTravailler en \xe9troite collaboration avec les m\xe9decins, les infirmiers et les professionnels param\xe9dicaux dans la prise en charge de cas complexes.\nInformer les patients et leurs familles sur les pathologies, les traitements et la pr\xe9vention..\nEncadrer le personnel infirmier et contribuer aux initiatives de formation du personnel afin de renforcer les comp\xe9tences cliniques de l'\xe9quipe.\nR\xe9pondre aux situations de soins aigus, engager les gestes de sauvetage et stabiliser les patients en \xe9tat critique.",competence1:"Doit faire preuve de remarquables capacit\xe9s d'analyse et savoir prendre des d\xe9cisions cliniques de mani\xe8re autonome.\nDoit rester calme et efficace dans des environnements rapides et sous forte pression.",competence2:"Doit \xeatre en bonne condition physique pour r\xe9pondre aux exigences de la prise en charge des patients, y compris les gardes prolong\xe9es et les urgences.\nDe solides comp\xe9tences de communication pour \xe9changer efficacement avec les patients, les familles et les \xe9quipes pluridisciplinaires, ainsi que des qualit\xe9s de leadership pour encadrer et guider le personnel.",competence3:"Doit avoir une sant\xe9 physique et mentale satisfaisante pour exercer les fonctions essentielles en toute s\xe9curit\xe9. Doit respecter toutes les politiques de l'h\xf4pital et les normes \xe9thiques.",diplome:"Doit \xeatre titulaire d'un Master of Science in Nursing (MSN) ou d'un Doctor of Nursing Practice (DNP) d'un programme accr\xe9dit\xe9. (( Cela doit faire partie de l'histoire de votre personnage. ))\nDoit poss\xe9der une licence RN active de San Andreas. (( **PNJ** ))\nDoit d\xe9tenir une certification nationale (board certification) dans un domaine de sp\xe9cialit\xe9 (ex. AANP, ANCC). (( **Cela doit faire partie de l'histoire de votre personnage**. ))\nAu minimum deux ann\xe9es d'exp\xe9rience clinique en soins infirmiers sont pr\xe9f\xe9rables. Une exp\xe9rience de NP dans un cadre de soins similaire est vivement souhait\xe9e."},"Student Nurse":{nom:"\xc9tudiant(e) Infirmier(\xe8re)",cle:"\xc9tudiant(e) Infirmier(\xe8re)",role:"Externe / \xc9tudiant(e) Infirmier(\xe8re)",presentation:"R\xe9aliser des t\xe2ches telles que la prise des constantes vitales, l'aide \xe0 l'hygi\xe8ne et le signalement des observations, sous la supervision directe d'un(e) RN ou d'un(e) LVN.\nSuivre des infirmiers exp\xe9riment\xe9s et participer \xe0 des actes non invasifs pour construire des connaissances de base.\nAider aux t\xe2ches administratives, au r\xe9approvisionnement et \xe0 l'entretien d'espaces de travail propres et organis\xe9s.\nParticiper aux s\xe9ances de formation, aux simulations et aux r\xe9unions de service pr\xe9vues pour renforcer les comp\xe9tences cliniques.",competence1:"Un esprit critique, un jugement d\xe9cisif et la capacit\xe9 de s'adapter \xe0 diverses situations cliniques sous supervision sont requis.",competence2:"La capacit\xe9 de travailler dans un environnement rapide et sous pression tout en gardant son calme est essentielle.\nLes candidat(e)s doivent \xeatre en bonne condition physique pour effectuer des t\xe2ches telles que d\xe9placer et soulever des patients, avec une mobilit\xe9 compl\xe8te du corps, une dext\xe9rit\xe9 manuelle des doigts et une bonne coordination \u0153il-main.",competence3:"Une communication efficace et le travail d'\xe9quipe sont obligatoires pour \xe9changer avec les patients, les familles et le personnel.\nLes candidat(e)s doivent r\xe9sider dans l'\xc9tat de San Andreas et avoir au moins 18 ans.\nNe doivent pas avoir \xe9t\xe9 condamn\xe9(e)s pour un crime ou un d\xe9lit pertinent par le pass\xe9.",diplome:"Doit conserver une sant\xe9 physique et mentale satisfaisante pour exercer les fonctions essentielles en toute s\xe9curit\xe9 et respecter toutes les politiques de l'h\xf4pital et r\xe8gles \xe9thiques."},"Nursing Intern":{nom:"Interne en Soins Infirmiers",cle:"Interne en Soins Infirmiers",role:"Aide Soignant(e)",presentation:"Assister les infirmiers dipl\xf4m\xe9s pour l'hygi\xe8ne, la mobilit\xe9, la nutrition et le confort des patients.\nR\xe9aliser des t\xe2ches cliniques de base, comme relever les constantes vitales, pr\xe9parer le mat\xe9riel et surveiller l'\xe9tat des patients, sous la supervision d'un(e) RN ou d'un(e) LVN.\nAssister aux formations continues, aux simulations et aux s\xe9ances de d\xe9veloppement du personnel pour renforcer les comp\xe9tences cliniques.\nVeiller \xe0 ce que les zones de soins soient propres, bien approvisionn\xe9es et organis\xe9es.",competence1:"Un esprit critique, un jugement d\xe9cisif et la capacit\xe9 de travailler aussi bien seul(e) qu'en collaboration au sein d'une \xe9quipe de soins sont requis.",competence2:"Doit faire preuve de r\xe9silience et de sang-froid dans un environnement clinique sous forte pression.\nLes candidat(e)s doivent pouvoir r\xe9pondre aux exigences physiques de la prise en charge des patients, notamment d\xe9placer et soulever des patients, avec une mobilit\xe9 compl\xe8te du corps et une motricit\xe9 fine.",competence3:"Une communication et une collaboration efficaces avec les patients, les familles et le personnel soignant sont essentielles.\nDoit avoir une sant\xe9 physique et mentale satisfaisante pour exercer les fonctions essentielles en toute s\xe9curit\xe9 et respecter toutes les politiques de l'h\xf4pital et r\xe8gles \xe9thiques.\nNe doit pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit pertinent par le pass\xe9.",diplome:"Doit avoir termin\xe9 au moins une ann\xe9e d'un programme de soins infirmiers approuv\xe9 par San Andreas ou en \xeatre r\xe9cemment dipl\xf4m\xe9(e). Doit fournir la preuve d'une inscription en cours ou r\xe9cente."},Paramedic:{nom:"Paramedic",cle:"Paramedic",role:"Paramedic",presentation:"Les paramedics sont des professionnels avanc\xe9s des soins pr\xe9-hospitaliers, charg\xe9s de r\xe9pondre aux appels m\xe9dicaux d'urgence, d'\xe9valuer l'\xe9tat des patients et de r\xe9aliser des interventions m\xe9dicales critiques. Ils travaillent dans des environnements dynamiques, souvent sous forte pression, pour stabiliser les patients et les transporter vers des \xe9tablissements de sant\xe9. Leurs principales responsabilit\xe9s incluent le maintien avanc\xe9 des fonctions vitales (ALS), l'administration de m\xe9dicaments et les soins de traumatologie.",competence1:"Ma\xeetrise des techniques de maintien avanc\xe9 des fonctions vitales (ALS) et des protocoles d'urgence m\xe9dicale.",competence2:"Solides capacit\xe9s de d\xe9cision et aptitude \xe0 rester calme et efficace sous pression.",competence3:"Excellentes comp\xe9tences de communication et de relations interpersonnelles avec les patients et l'\xe9quipe.",diplome:"Avoir termin\xe9 un programme de Paramedic accr\xe9dit\xe9 et d\xe9tenir la certification / licence d'\xc9tat en cours de validit\xe9 de Paramedic. Permis de conduire valide."},EMT:{nom:"Technicien(ne) Ambulancier(\xe8re) (EMT)",cle:"Technicien(ne) Ambulancier(\xe8re) (EMT)",role:"Technicien(ne) Ambulancier(\xe8re) (EMT)",presentation:"Les EMT assurent le maintien de base des fonctions vitales (BLS) et les soins m\xe9dicaux d'urgence aux patients sur les lieux d'un incident et pendant le transport vers l'h\xf4pital. Ils \xe9valuent l'\xe9tat des patients, g\xe8rent les voies a\xe9riennes, contr\xf4lent les saignements et aident \xe0 l'administration de m\xe9dicaments sous direction m\xe9dicale. Les EMT sont des premiers intervenants essentiels du syst\xe8me de secours m\xe9dical d'urgence.",competence1:"Ma\xeetrise des comp\xe9tences de maintien de base des fonctions vitales (BLS) et de l'\xe9valuation du patient.",competence2:"Capacit\xe9 \xe0 travailler efficacement en \xe9quipe et \xe0 suivre pr\xe9cis\xe9ment les protocoles m\xe9dicaux.",competence3:"Bonne endurance physique et capacit\xe9 \xe0 soulever et d\xe9placer les patients en toute s\xe9curit\xe9.",diplome:"Avoir termin\xe9 un programme d'EMT accr\xe9dit\xe9 et d\xe9tenir la certification / licence d'\xc9tat en cours de validit\xe9 d'EMT. Permis de conduire valide."},"Part-Time EMS Program":{nom:"Programme EMS \xe0 Temps Partiel",cle:"Programme EMS \xe0 Temps Partiel",role:"",presentation:"Le programme EMS \xe0 temps partiel offre des opportunit\xe9s flexibles aux EMT et Paramedics certifi\xe9s pour contribuer aux secours m\xe9dicaux d'urgence \xe0 temps partiel. Les participants r\xe9pondent aux appels, dispensent les soins aux patients et travaillent aux c\xf4t\xe9s du personnel \xe0 temps plein, tout en entretenant leurs comp\xe9tences et en servant la communaut\xe9. Ce programme est id\xe9al pour celles et ceux qui souhaitent concilier le travail en EMS avec d'autres engagements.",competence1:"Certification / licence d'EMT ou de Paramedic en cours de validit\xe9 et en r\xe8gle.",competence2:"Capacit\xe9 \xe0 s'adapter \xe0 des horaires et \xe0 des environnements de travail variables.",competence3:"Engagement \xe0 maintenir sa comp\xe9tence clinique et \xe0 respecter les protocoles EMS.",diplome:"Certification / licence d'\xc9tat valide d'EMT ou de Paramedic. Une exp\xe9rience pr\xe9alable sur le terrain est souvent pr\xe9f\xe9r\xe9e."},"Coroner Internship":{nom:"Interne M\xe9dico-L\xe9gal(e)",cle:"Interne M\xe9dico-L\xe9gal(e)",role:"Interne M\xe9dico-L\xe9gal(e)",presentation:"En tant qu'interne au sein de notre d\xe9partement, vous pourrez accompagner nos \xe9quipes sur le terrain et assister \xe0 l'essentiel de notre travail, de l'investigation de base sur une sc\xe8ne de crime au transport des corps. Vous pourrez \xe9galement assister \xe0 des autopsies et ainsi observer comment nos m\xe9decins l\xe9gistes \xe9tablissent la cause du d\xe9c\xe8s de quelqu'un.\nVos missions consisteront principalement \xe0 suivre nos Coroners sur le terrain ; bien que vous ne puissiez pas interagir directement avec la sc\xe8ne, on pourra vous demander un r\xe9sum\xe9 de ce que vous avez vu sur une sc\xe8ne afin de d\xe9velopper vos comp\xe9tences en investigation de terrain. Vous pourrez aussi observer des autopsies et suivre l'ensemble de leur d\xe9roulement, avec des occasions de vous exercer vous-m\xeame ; bien s\xfbr, vous vous entra\xeenerez sur des animaux comme des porcs et non sur de v\xe9ritables cadavres humains.",competence1:"Un estomac solide et la capacit\xe9 de bien fonctionner sous un stress extr\xeame.",competence2:"Avoir au moins dix-huit (18) ans et poss\xe9der une adresse l\xe9gale dans l'\xc9tat de San Andreas.\nUne bonne aptitude \xe0 travailler en \xe9quipe et \xe0 suivre les directives.",competence3:"Ne pas avoir \xe9t\xe9 condamn\xe9(e) pour un crime ou un d\xe9lit r\xe9cent.",diplome:"\xcatre inscrit(e) dans un coll\xe8ge ou une universit\xe9 dont l'accr\xe9ditation est reconnue aux \xc9tats-Unis d'Am\xe9rique."},"Medical Examiner":{nom:"M\xe9decin L\xe9giste",cle:"M\xe9decin L\xe9giste",role:"M\xe9decin L\xe9giste",presentation:"Les m\xe9decins l\xe9gistes (\xab medical examiners \xbb), \xe9galement appel\xe9s pathologistes m\xe9dico-l\xe9gaux, sont des m\xe9decins sp\xe9cialistes form\xe9s \xe0 la pathologie m\xe9dico-l\xe9gale et anatomique. Ils utilisent leurs comp\xe9tences m\xe9dicales pour d\xe9terminer la cause du d\xe9c\xe8s, qu'elle soit naturelle, accidentelle ou intentionnelle. Ils peuvent \xe9galement \xeatre amen\xe9s \xe0 t\xe9moigner dans des affaires judiciaires o\xf9 leurs comp\xe9tences ont \xe9t\xe9 utilis\xe9es. En outre, ils peuvent recueillir et examiner des \xe9l\xe9ments de preuve pour d\xe9terminer la cause du d\xe9c\xe8s dans des affaires criminelles et des d\xe9c\xe8s non naturels ou non surveill\xe9s. Ils peuvent aussi \xeatre pr\xe9sents sur les lieux du d\xe9c\xe8s pour s'assurer que les \xe9l\xe9ments de preuve recueillis sont transport\xe9s en toute s\xe9curit\xe9 vers le laboratoire pour analyse. Il revient au m\xe9decin l\xe9giste d'obtenir les dossiers m\xe9dicaux aupr\xe8s des h\xf4pitaux et des cabinets pour \xe9valuation. Une fois leur enqu\xeate termin\xe9e, les m\xe9decins l\xe9gistes r\xe9sument leurs conclusions par \xe9crit et les pr\xe9sentent oralement. Ils peuvent intervenir en tant qu'experts et t\xe9moigner lors d'audiences pr\xe9liminaires et de proc\xe8s. Les responsabilit\xe9s d'un m\xe9decin l\xe9giste adjoint seront de r\xe9aliser des autopsies pour d\xe9terminer la cause du d\xe9c\xe8s, d'entreprendre l'examen de pr\xe9l\xe8vements, de tissus, d'organes, de fluides et de sang pour d\xe9terminer les anomalies ayant pu entra\xeener le d\xe9c\xe8s, d'enqu\xeater sur les d\xe9c\xe8s soudains et/ou non naturels en lien avec les forces de l'ordre, tout en r\xe9digeant des rapports de conclusions et en fournissant des t\xe9moignages d'expert devant les tribunaux. Tout au long de leur exercice, ils restent inform\xe9s des \xe9volutions de la pathologie m\xe9dico-l\xe9gale et suivent des s\xe9minaires ainsi que des cours de m\xe9decine l\xe9gale dans le cadre de la formation continue et de la recherche.",competence1:"Connaissance pratique des lois et r\xe8glements applicables aux services m\xe9dico-l\xe9gaux.",competence2:"Exceptionnelles capacit\xe9s d'analyse et de recherche.",competence3:"Exp\xe9rience de l'utilisation d'\xe9quipements de tests de laboratoire.\nExcellentes comp\xe9tences de communication et de r\xe9daction.",diplome:"Doit \xeatre titulaire d'un Bachelor's degree en biologie, en sciences physiques ou dans un domaine connexe\nDipl\xf4me de m\xe9decine (doctorat) et certificat USMLE."},"Coroner Investigator":{nom:"Enqu\xeateur(trice) M\xe9dico-L\xe9gal(e)",cle:"Enqu\xeateur(trice) M\xe9dico-L\xe9gal(e)",role:"Enqu\xeateur(trice) M\xe9dico-L\xe9gal(e)",presentation:"Les enqu\xeateurs m\xe9dico-l\xe9gaux enqu\xeatent et \xe9tablissent des rapports sur les d\xe9c\xe8s relevant de la comp\xe9tence du Los Santos Department of Medical Examiner-Coroner. Les titulaires de ce poste prennent en charge la sc\xe8ne du d\xe9c\xe8s et le corps de la personne d\xe9c\xe9d\xe9e, prot\xe8gent les effets personnels du d\xe9funt, localisent et pr\xe9viennent les proches et accomplissent les autres missions requises. En plus d'examiner les corps et les sc\xe8nes de crime, ce r\xf4le vise \xe0 accomplir diverses t\xe2ches administratives, \xe0 tenir des registres pr\xe9cis des constatations et \xe0 pr\xe9senter ces constatations devant un tribunal si n\xe9cessaire. Ce poste exige d'excellentes comp\xe9tences de communication et de r\xe9daction. De plus, lorsqu'une personne est responsable d'une \xe9quipe de la morgue, elle peut \xe9galement superviser le travail des assistants de morgue ou des techniciens d'autopsie. Les responsabilit\xe9s d'un enqu\xeateur m\xe9dico-l\xe9gal vont de l'investigation des d\xe9c\xe8s relevant de la comp\xe9tence du d\xe9partement \xe0 l'aide \xe0 l'\xe9tablissement de la cause, de la mani\xe8re et des circonstances du d\xe9c\xe8s, en passant par la concertation avec les forces de l'ordre pour coordonner les enqu\xeates sur les d\xe9c\xe8s r\xe9sultant d'actes criminels et l'identification formelle des d\xe9funts par la prise d'empreintes digitales et de photographies afin de constituer des dossiers. Un enqu\xeateur m\xe9dico-l\xe9gal peut informer la famille du d\xe9funt, interroger des t\xe9moins, des m\xe9decins, des forces de l'ordre et des membres de la famille pour obtenir les faits concernant les d\xe9c\xe8s. Il est responsable du transport des corps et peut travailler sur des projets sp\xe9ciaux qui lui sont confi\xe9s, tout en remplissant les certificats de d\xe9c\xe8s et en d\xe9cidant du moment o\xf9 un d\xe9funt peut \xeatre lib\xe9r\xe9.",competence1:"Connaissance pratique des lois et r\xe8glements applicables aux services m\xe9dico-l\xe9gaux.",competence2:"Exceptionnelles capacit\xe9s d'analyse et de recherche.",competence3:"Exp\xe9rience de l'utilisation d'\xe9quipements de tests de laboratoire.\nExcellentes comp\xe9tences de communication et de r\xe9daction.",diplome:"Doit \xeatre titulaire d'un Bachelor's degree en biologie, en sciences physiques ou dans un domaine connexe."},"Trainee Forensic Attendant":{nom:"Stagiaire M\xe9dico-L\xe9gal(e)",cle:"Stagiaire M\xe9dico-L\xe9gal(e)",role:"Stagiaire M\xe9dico-L\xe9gal(e)",presentation:"Les nouveaux candidats suivront une formation dispens\xe9e par notre \xe9tablissement pour devenir Coroner ; en tant que nouvelle recrue, votre mission principale est de terminer le programme de formation de terrain et de devenir un(e) Coroner pleinement qualifi\xe9(e). Vous aurez les m\xeames missions qu'un Coroner, mais vous n'aurez pas le droit de recevoir des appels seul(e) tant que vous n'aurez pas termin\xe9 votre phase de formation de terrain. Les nouvelles recrues deviendront l'\xe9pine dorsale de tout le d\xe9partement, formant le plus fort pourcentage de ses membres. Sans les nouvelles recrues, les missions quotidiennes deviendront difficiles : le d\xe9partement a besoin de nouvelles recrues pour se maintenir. Les nouvelles recrues sont encourag\xe9es \xe0 se consacrer au d\xe9partement et seront probablement le principal point de contact avec le public au quotidien, car elles traiteront les appels les plus courants. En tant que Stagiaire M\xe9dico-L\xe9gal employ\xe9(e) au Pillbox Hill Medical Center, vous serez form\xe9(e) \xe0 la r\xe9ponse sur le terrain aux appels entrants, o\xf9 vous serez utile au public, aux autres d\xe9partements et, surtout, \xe0 vos propres coll\xe8gues.",competence1:"Un haut niveau de ma\xeetrise de l'\xe9crit est requis, ainsi que la capacit\xe9 de r\xe9diger \xe0 temps des courriers \xe0 destination des d\xe9partements voisins.",competence2:"La capacit\xe9 de travailler dans un environnement stressant et d'agir de mani\xe8re appropri\xe9e est indispensable.",competence3:"Le ou la candidat(e) doit \xeatre en bonne condition physique pour r\xe9pondre \xe0 des exigences telles que d\xe9placer et soulever des corps, avec une mobilit\xe9 compl\xe8te du corps, une dext\xe9rit\xe9 manuelle des doigts et une bonne coordination \u0153il-main.",diplome:"Les candidat(e)s doivent poss\xe9der au minimum un dipl\xf4me de fin d'\xe9tudes secondaires (high school diploma)\nDoit avoir un \xe9tat de sant\xe9 physique et mental satisfaisant pour exercer les fonctions essentielles du poste en toute s\xe9curit\xe9."}}}}]);
